'use client'

import { useEffect, useState } from 'react'

type Shift = {
	id: number
	cashStart: number | null
	cashEnd: number | null
	openedAt: string | null
	closedAt: string | null
}

export default function ShiftsArchivePage() {
	const [shifts, setShifts] = useState<Shift[]>([])

	useEffect(() => {
		fetch('/api/admin/shifts')
			.then((res) => res.json())
			.then((json) => {
				setShifts(Array.isArray(json.data) ? json.data : [])
			})
	}, [])

	return (
		<div>
			<h1>Архів змін</h1>

			{shifts.length === 0 ? (
				<p>Поки що немає закритих змін</p>
			) : (
				<table border={1} cellPadding={8}>
					<thead>
						<tr>
							<th>ID</th>
							<th>Відкрито</th>
							<th>Закрито</th>
							<th>Каса 1</th>
							<th>Каса 2</th>
							<th>Деталі</th>
						</tr>
					</thead>
					<tbody>
						{shifts.map((s) => (
							<tr key={s.id}>
								<td>{s.id}</td>
								<td>{s.openedAt}</td>
								<td>{s.closedAt}</td>
								<td>{s.cashStart}</td>
								<td>{s.cashEnd}</td>
								<td>
									<a href={`/admin/shifts/${s.id}`}>Відкрити</a>
								</td>
							</tr>
						))}
					</tbody>
				</table>
			)}
		</div>
	)
}